import { TOO_LARGE, body, clientIp, fail, json, rateLimit } from '@/lib/server/http';
import {
  deleteRoom,
  drainSignals,
  getRoom,
  listPeers,
  normalizeCode,
  pushSignal,
  roomExpired,
  validCode,
} from '@/lib/server/rooms';
import { auth } from '@/lib/server/tokens';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

/* `join` is generated by the server only. Everything else is peer-to-peer
 * WebRTC signaling relayed through short-lived mailboxes. */
const ALLOWED = new Set(['offer', 'answer', 'ice', 'ready', 'leave', 'error', 'relay']);

export async function POST(request) {
  const payload = auth(request);
  if (!payload) return fail('unauthorized', 401);
  if (!rateLimit(`signal:${clientIp(request)}:${payload.peerId}`, 240, 60_000)) {
    return fail('rate_limited', 429);
  }
  const input = await body(request, 32 * 1024);
  if (input === TOO_LARGE) return fail('payload_too_large', 413);

  const code = normalizeCode(input.room || payload.room);
  if (code !== payload.room || !validCode(code)) return fail('forbidden', 403);
  const type = String(input.type || '');
  if (!ALLOWED.has(type)) return fail('bad_signal_type', 400);
  const to = String(input.to || '');
  if (!/^p_[A-Za-z0-9]{1,32}$/.test(to)) return fail('missing_target', 400);

  const room = await getRoom(code);
  if (!room) return fail('room_not_found', 404);
  if (roomExpired(room)) {
    await deleteRoom(code);
    return fail('room_expired', 410);
  }

  /* Star topology: clients may only signal the host, and the host may only
   * signal a client that belongs to this room. */
  if (payload.role === 'client') {
    if (room.hostPeerId !== to) return fail('forbidden', 403);
  } else {
    if (to === room.hostPeerId) return fail('forbidden', 403);
    const peers = await listPeers(code);
    if (!peers.some((p) => p.id === to && p.role !== 'host')) {
      return fail('peer_not_found', 404);
    }
  }

  const data = input.data ?? null;
  let encoded;
  try {
    encoded = JSON.stringify(data);
  } catch {
    return fail('bad_signal_data', 400);
  }
  if (encoded && encoded.length > 24_000) return fail('signal_too_large', 413);

  await pushSignal(code, to, {
    from: payload.peerId,
    type,
    data,
    ts: Date.now(),
  });
  return json({ ok: true });
}

export async function GET(request) {
  const payload = auth(request);
  if (!payload) return fail('unauthorized', 401);
  if (!rateLimit(`poll:${clientIp(request)}:${payload.peerId}`, 180, 60_000)) {
    return fail('rate_limited', 429);
  }
  const url = new URL(request.url);
  const code = normalizeCode(url.searchParams.get('room') || payload.room);
  if (code !== payload.room) return fail('forbidden', 403);

  const peers = await listPeers(code);
  if (!peers.some((p) => p.id === payload.peerId)) return fail('peer_not_found', 410);

  const messages = await drainSignals(code, payload.peerId);
  return json({ ok: true, messages });
}
